SELECT i.*,m.canonical_market_key,m.canonical_base_asset,m.canonical_base_units_per_venue_base_unit,b.minute_time,b.valid_bitmap,b.bid_price_01,b.bid_qty_01,b.ask_price_01,b.ask_qty_01 FROM crypto_market_info_perp_soak.order_book_minute AS b FINAL INNER JOIN crypto_market_info_perp_soak.instrument AS i FINAL USING(instrument_id) INNER JOIN crypto_market_info_perp_soak.instrument_canonical_mapping AS m FINAL ON m.instrument_id=b.instrument_id INNER JOIN crypto_market_info_perp_soak.perpetual_universe_member AS u FINAL ON u.instrument_id=b.instrument_id WHERE b.minute_time='2026-09-12 19:12:00' AND bitTest(b.valid_bitmap,0) AND u.run_id=(SELECT argMax(run_id,started_at) FROM crypto_market_info_perp_soak.perpetual_universe_run FINAL) AND m.mapping_revision=(SELECT argMax(mapping_revision,started_at) FROM crypto_market_info_perp_soak.perpetual_universe_run FINAL)
